mapper.select:
select t.doctype as docType,
       max(t.doctypename) as docTypeName,
       sum(t.c) as docCount
  from (

    ( select doctype, doctypename, count(1) as c
        from sdsorder.u_f_docmain_${suffix}
       where shop_code = #{shopCode}
         and confirmstate = '待审核'

         and (doctype != #{ownedDocType} or createuser = #{owner})

       group by doctype, doctypename )

  ) t
 group by t.doctype
 order by docCount desc, t.doctype

select.foreach:
( select '${suffix}' as `month`,
         coalesce(sum(case when change_qty > 0 then cost_amount else 0 end), 0)      as inboundAmount,
         abs(coalesce(sum(case when change_qty < 0 then cost_amount else 0 end), 0)) as outboundAmount
    from sdsorder.u_f_ledger_${suffix}
   where shop_code = #{shopCode}

     and doc_type not in

        #{excludeType}


)

( select '${suffix}' as `month`,
         coalesce(sum(case when transtype = '收入' then abs(amount) else 0 end), 0)  as incomeAmount,
         coalesce(sum(case when transtype = '支出' then abs(amount) else 0 end), 0)  as expenseAmount
    from sdsorder.u_f_transaction_${suffix}
   where shop_code = #{shopCode}
     and status = '已完成' )

mapper.select:
select t.docMonth, t.docCount
  from (

    ( select '${suffix}' as docMonth, count(1) as docCount
        from sdsorder.u_o_order_${suffix}
       where shop_code = #{shopCode}
         and orderstate = '待审核'

         and staffcode = #{owner}

    )

  ) t
 where t.docCount > 0
 order by t.docMonth desc

select coalesce(nullif(trim(currency), ''), 'CNY') as currency,
       coalesce(sum(totalamount), 0)               as amount,
       count(1)                                    as orderCount
  from sdsorder.u_o_order_${suffix}
 where shop_code = #{shopCode}
   and orderstate in ('已备货', '备货中', '发货中', '已完成')

   and staffcode = #{owner}

 group by coalesce(nullif(trim(currency), ''), 'CNY')
 order by amount desc

select count(1) as activeCount,
       coalesce(sum(case when expectdate is not null and expectdate < #{today}
                         then 1 else 0 end), 0) as overdueCount
  from sdsshop.u_p_purchase
 where shop_code = #{shopCode}
   and status in ('approved', 'partial_received')

select count(1) as activeCount,
       coalesce(sum(case when plandate is not null and plandate < #{today}
                         then 1 else 0 end), 0) as overdueCount
  from sdsshop.u_p_production
 where shop_code = #{shopCode}
   and status in ('待生产', '待领料', '生产中')
